import {demoFor,searchDemos,canonicalQuery,curatedDemo,validDemoUrl,sourceSearchUrl} from './exercise-demos.js';
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
const KEY='dayone-gym-store-v1';
const defaultStore=()=>({profile:{name:'',weight:'',goal:'',unit:'kg'},days:{},health:{daily:{}},photoAlignments:{},exerciseDemos:{}});
let store;
try{const parsed=JSON.parse(localStorage.getItem(KEY)||'null');store={...defaultStore(),...(parsed||{}),profile:{...defaultStore().profile,...(parsed?.profile||{})},days:parsed?.days||{},health:{daily:parsed?.health?.daily||{}},photoAlignments:parsed?.photoAlignments||{},exerciseDemos:parsed?.exerciseDemos||{}};delete store.firebaseConfig}catch{store=defaultStore()}
const istIso=()=>{let a=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());let v=Object.fromEntries(a.map(x=>[x.type,x.value]));return `${v.year}-${v.month}-${v.day}`};
const realDay=dayForDate(istIso());
let ui={tab:'today',day:clamp(realDay,1,100),expanded:'0',libraryTab:'pdf',libraryPhase:0,search:'',timerLeft:90,timerEnd:0,timerActive:false,timerHandle:null,viewWeek:null,showNotes:false,photoAngle:'front',compareA:1,compareB:clamp(realDay,1,100),compareAngle:'front',compareMode:'overlay',compareReveal:50};
let register={lessons:[],resources:[],gaps:[]};
let demoStatus={},demoResults={};
function setDemoStatus(index,text){demoStatus[index]=text;const el=document.getElementById('demo-status-'+index);if(el)el.textContent=text;}
function storeDemo(name,demo){store.exerciseDemos??={};store.exerciseDemos[name]={...demo,_updatedAt:Date.now()};save();queueCloudSync();}
function demoPanel(ex,i){const custom=store.exerciseDemos?.[ex.name],builtin=curatedDemo(ex.name),record=demoFor(ex.name,custom);const saved=!!custom&&!custom._deleted;return `<div class="demo-panel"><div class="demo-title"><strong>Movement demo</strong><span>${saved?'Chosen reference':record?'Illustrative · check variation':'External reference'}</span></div>${record?`<div class="demo-media">${/\.(mp4|webm)(\?|$)/i.test(record.url)?`<video muted loop playsinline controls preload="none" src="${esc(record.url)}" aria-label="${esc(ex.name)} exercise reference"></video>`:`<img src="${esc(record.url)}" alt="${esc(record.title||ex.name)} movement demonstration" loading="lazy" referrerpolicy="no-referrer" onerror="this.hidden=true;this.nextElementSibling.hidden=false">`}<div class="demo-error" hidden>Could not load this animation. Try Find GIF or view the reference.</div></div><div class="demo-attribution">${esc(record.title||ex.name)} · ${esc(record.provider||'External source')} · <a href="${esc(record.source||record.url)}" target="_blank" rel="noopener noreferrer">Source / licence ↗</a></div>`:`<div class="demo-empty">No verified exact GIF selected yet. Find a demonstration and check its equipment, angle and variation before using it.</div>`}<div class="demo-actions"><button class="secondary" data-action="demo-find" data-index="${i}" type="button">${ico('book',14)} Find GIF</button><button class="secondary" data-action="demo-link" data-index="${i}" type="button">Use my link</button>${saved?`<button class="ghost" data-action="demo-remove" data-index="${i}" type="button">Remove</button>`:''}</div><div class="demo-results" id="demo-results-${i}">${(demoResults[i]||[]).map((r,j)=>`<button class="demo-option" data-action="demo-select" data-index="${i}" data-result="${j}" type="button"><span><strong>${esc(r.name)}</strong><small>${esc(r.equipment||'Equipment unspecified')} · ${esc(r.provider)}</small></span><span>Choose ↗</span></button>`).join('')}</div><p class="demo-status" id="demo-status-${i}" aria-live="polite">${esc(demoStatus[i]||'')}</p><p class="demo-fineprint">This is a third-party technique example, not an Akash Fitness lesson. <a href="${esc(sourceSearchUrl(ex.name))}" target="_blank" rel="noopener noreferrer">Find technique guidance on ExRx ↗</a></p></div>`}
let siteSettings={bundlePdfs:true};
