  let local=await photoGet(day,angle);
  if(!local && sync.connected && (dayData(day).photos?.[angle] || (angle==='front'&&dayData(day).hasLocalPhoto))){
   try{const blob=await apiRequest(`?op=photo&day=${day}&angle=${angle}`,{method:'GET'},true);local=URL.createObjectURL(blob)}catch{}
  }
