function exportJSON(){const payload={app:'DAYONE Gym',version:2,exportedAt:new Date().toISOString(),start:START,profile:store.profile,days:store.days,health:store.health,photoAlignments:store.photoAlignments,exerciseDemos:store.exerciseDemos};let blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`dayone-backup-${istIso()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('JSON backup exported')}
async function importFile(file){try{const data=JSON.parse(await file.text());if(data.app!=='DAYONE Gym'||![1,2].includes(data.version)||!data.days||typeof data.days!=='object')throw Error('Not a DAYONE backup');if(!confirm('Merge this backup with the local workout log? Newer edits take priority.'))return;let changed=0;for(const [day,obj]of Object.entries(data.days)){if(!/^\d+$/.test(day)||Number(day)<1||Number(day)>100||!obj||typeof obj!=='object')continue;if((obj._updatedAt||0)>=(dayData(day)._updatedAt||0)){store.days[day]=obj;changed++}}if((data.profile?._updatedAt||0)>=(store.profile._updatedAt||0))store.profile={...store.profile,...data.profile};for(const [date,row]of Object.entries(data.health?.daily||{}))if((row._updatedAt||0)>=(store.health.daily[date]?._updatedAt||0))store.health.daily[date]=row;
 for(const [key,record]of Object.entries(data.photoAlignments||{}))if((record?._updatedAt||0)>=(store.photoAlignments?.[key]?._updatedAt||0)){store.photoAlignments??={};store.photoAlignments[key]=record;}
 for(const [key,record]of Object.entries(data.exerciseDemos||{}))if((record?._updatedAt||0)>=(store.exerciseDemos?.[key]?._updatedAt||0)){store.exerciseDemos??={};store.exerciseDemos[key]=record;}save();queueCloudSync();toast(`${changed} day logs imported`);render()}catch(e){toast(e.message||'Import failed')}}
// Netlify-only cloud sync. No secret is ever baked into the deployed bundle.
const apiUrl='/.netlify/functions/dayone-api';
function dataURLtoBlob(data){let base64=data.split(',')[1];let binary=atob(base64),bytes=new Uint8Array(binary.length);for(let i=0;i<bytes.length;i++)bytes[i]=binary.charCodeAt(i);return new Blob([bytes],{type:'image/jpeg'})}
async function apiRequest(query='',options={},binary=false){
  if(!navigator.onLine)throw Error('Offline. Your log is saved locally.');
  const response=await fetch(apiUrl+query,{...options,headers:{Authorization:'Bearer '+sync.key,...(options.headers||{})},cache:'no-store'});
  if(!response.ok){let err=await response.json().catch(()=>({}));throw Error(err.error||`Sync error ${response.status}`)}
  return binary?await response.blob():await response.json();
}
function queueCloudSync(){if(!sync.connected)return;sync.pending=true;clearTimeout(sync.queue);sync.queue=setTimeout(()=>pushCloud(),1800)}
async function connectCloud(){let key=$('netlify-key')?.value.trim()||sync.key;if(key.length<20)return toast('Enter the Netlify sync key (20+ characters).');const rememberKey=!!$('remember-sync')?.checked;sync.key=key;sync.status='Connecting…';render({keepScroll:true});try{await pullCloud(true);sync.connected=true;sync.status='Netlify connected';if(rememberKey)localStorage.setItem('dayone-netlify-secret',key);else localStorage.removeItem('dayone-netlify-secret');save();render({keepScroll:true});await pushCloud();await syncLocalPhotos();toast('Cloud log connected')}catch(e){sync.connected=false;sync.status='Device only';toast(e.message);render({keepScroll:true})}}
async function pullCloud(quiet=false){
  if(sync.busy)return;
  const {data}=await apiRequest('?op=state');
  if(data?.app==='DAYONE Gym'){
    for(const [day,remote]of Object.entries(data.days||{}))if(/^\d+$/.test(day)&&Number(day)>=1&&Number(day)<=100&&(remote._updatedAt||0)>(dayData(day)._updatedAt||0))store.days[day]=remote;
    if((data.profile?._updatedAt||0)>(store.profile?._updatedAt||0))store.profile={...store.profile,...data.profile};
    for(const [date,row]of Object.entries(data.health?.daily||{}))if((row._updatedAt||0)>(store.health.daily[date]?._updatedAt||0))store.health.daily[date]=row;
    for(const [key,record] of Object.entries(data.photoAlignments||{}))if((record?._updatedAt||0)>(store.photoAlignments?.[key]?._updatedAt||0)){store.photoAlignments??={};store.photoAlignments[key]=record;alignPair='';}
    for(const [key,record] of Object.entries(data.exerciseDemos||{}))if((record?._updatedAt||0)>(store.exerciseDemos?.[key]?._updatedAt||0)){store.exerciseDemos??={};store.exerciseDemos[key]=record;}
    save();
  }
  if(!quiet){sync.status='Netlify connected';render({keepScroll:true})}
}
async function pushCloud(){
  if(!sync.connected||sync.busy)return;
  sync.busy=true;sync.pending=false;sync.status='Saving…';
  try{
    // Merge before putting the snapshot to reduce clobbering when changing devices.
    const {data}=await apiRequest('?op=state');
    if(data?.app==='DAYONE Gym'){
      for(const [day,remote]of Object.entries(data.days||{}))if(/^\d+$/.test(day)&&Number(day)>=1&&Number(day)<=100&&(remote._updatedAt||0)>(dayData(day)._updatedAt||0))store.days[day]=remote;
      if((data.profile?._updatedAt||0)>(store.profile._updatedAt||0))store.profile={...store.profile,...data.profile};
      for(const [date,row]of Object.entries(data.health?.daily||{}))if((row._updatedAt||0)>(store.health.daily[date]?._updatedAt||0))store.health.daily[date]=row;
    for(const [key,record] of Object.entries(data.photoAlignments||{}))if((record?._updatedAt||0)>(store.photoAlignments?.[key]?._updatedAt||0)){store.photoAlignments??={};store.photoAlignments[key]=record;}
    for(const [key,record] of Object.entries(data.exerciseDemos||{}))if((record?._updatedAt||0)>(store.exerciseDemos?.[key]?._updatedAt||0)){store.exerciseDemos??={};store.exerciseDemos[key]=record;}
    }
    save();
    const payload={app:'DAYONE Gym',version:2,days:store.days,profile:store.profile,health:store.health,photoAlignments:store.photoAlignments,exerciseDemos:store.exerciseDemos,updatedAt:Date.now()};
    await apiRequest('?op=state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
    sync.status='Netlify connected';
  }catch(e){sync.status='Sync pending';console.warn('Cloud sync:',e);toast('Cloud retry needed: '+e.message);sync.pending=true}
  finally{sync.busy=false;if(sync.pending&&navigator.onLine)queueCloudSync();if(ui.tab==='settings')render({keepScroll:true})}
}
window.addEventListener('online',()=>{if(sync.connected)pullCloud().then(()=>pushCloud()).catch(()=>{sync.status='Sync pending'})});

