async function runPhotoAlignment(manual=false){
 restoreAlignment();const before=$('compare-before-img'),after=$('compare-after-img');const key=comparisonKey();
 if(!before?.naturalWidth||!after?.naturalWidth){if(manual)toast('Select two progress photos first.');return}
 if(alignBusy||(!manual&&triedPairs.has(key)))return;
 if(!manual&&readAlignmentMap()[key]&&!readAlignmentMap()[key]._deleted)return; // honor person's saved fine adjustments
 if(!navigator.onLine && localStorage.getItem('dayone-pose-local-ready')!=='1'){setAlignStatus('Offline: manual alignment works now. Auto align needs internet for initial model download.');return}
 triedPairs.add(key);alignBusy=true;setAlignStatus('Detecting shoulders and hips locally on your device…');
 const action=$('auto-align-btn');if(action)action.disabled=true;
 try{
  setCompareMode('overlay');
  const {autoAlignPhotos}=await import('./photo-align.js');
  if(key!==comparisonKey())return;
  const result=await autoAlignPhotos(before,after,$('compare-overlay'));
  if(key!==comparisonKey())return;
  alignTransform={scale:result.scale,dx:result.dx,dy:result.dy,angle:result.angle};
  alignStatus=result.quality==='good'?`Aligned from ${result.landmarks} body landmarks · review the result.`:`Approximate fit from ${result.landmarks} landmarks · perspective or pose differs; fine-tune below.`;
  saveManualAlignment();syncCompareControls();
 }catch(err){if(key===comparisonKey())setAlignStatus(`${err.message||'Automatic alignment unavailable.'} You can still align manually.`)}
 finally{alignBusy=false;if(action?.isConnected)action.disabled=false}
}
function photoSlotOptions(current){return Array.from({length:100},(_,i)=>i+1).map(d=>`<option value="${d}" ${d===current?'selected':''}>Day ${d} · ${dateLabel(dateFor(d),true)}</option>`).join('')}
function comparePanel(){
  restoreAlignment();
  const d=ui.day;
  return `<section class="card comparison" style="margin-top:16px">
    <div class="section-head"><h2>Photo comparison</h2><span class="pill">Private · on-device alignment</span></div>
    <p class="page-sub" style="margin:3px 0 16px">Compare real body changes without distorted stretching or filters. Automatic positioning matches visible shoulders and hips when possible; different camera perspectives still need a visual check.</p>
    <div class="capture-buttons">${['front','side','back'].map(angle=>`<button class="secondary" data-action="photo-day" data-day="${d}" data-angle="${angle}">${ico('camera',15)} ${angle[0].toUpperCase()+angle.slice(1)} · D${d}</button>`).join('')}</div>
    <div class="compare-controls"><label>BEFORE<select class="select" id="compare-a">${photoSlotOptions(ui.compareA)}</select></label><label>AFTER<select class="select" id="compare-b">${photoSlotOptions(ui.compareB)}</select></label><label>VIEW<select class="select" id="compare-angle"><option value="front" ${ui.compareAngle==='front'?'selected':''}>Front</option><option value="side" ${ui.compareAngle==='side'?'selected':''}>Side</option><option value="back" ${ui.compareAngle==='back'?'selected':''}>Back</option></select></label></div>
    <div class="comparison-toolbar"><div class="view-toggle" role="group" aria-label="Comparison mode"><button data-action="compare-mode" data-mode="overlay" class="${ui.compareMode==='overlay'?'selected':''}">Overlay</button><button data-action="compare-mode" data-mode="split" class="${ui.compareMode==='split'?'selected':''}">Side by side</button></div><button class="secondary align-action" id="auto-align-btn" data-action="compare-auto">${ico('bolt',15)} Auto align</button><button class="secondary align-reset" data-action="compare-reset" aria-label="Reset photo alignment">Reset</button></div>
    <p class="alignment-status" id="align-status" role="status">${esc(alignStatus)}</p>
    <div class="compare-grid" id="compare-split" ${ui.compareMode==='overlay'?'hidden':''}>${[['BEFORE',ui.compareA],['AFTER',ui.compareB]].map(([label,day])=>`<div class="compare-shot"><div class="photo-placeholder">${ico('camera',26)}<span>${label}<br>Day ${day}</span></div><img data-compare-day="${day}" data-angle="${ui.compareAngle}" alt="${label.toLowerCase()} Day ${day} ${ui.compareAngle} photo" style="display:none" loading="lazy"><div class="photo-shot-label">${label} · Day ${day}</div></div>`).join('')}</div>
    <div class="compare-overlay-area" id="compare-overlay-area" ${ui.compareMode==='split'?'hidden':''}>
      <div class="compare-overlay" id="compare-overlay" aria-label="Aligned comparison; drag photo to adjust its position"><div class="photo-placeholder" id="overlay-placeholder">${ico('camera',27)}<span>Add two photos to begin comparing.</span></div>
        <img id="compare-before-img" data-compare-day="${ui.compareA}" data-angle="${ui.compareAngle}" alt="Before photo, Day ${ui.compareA}" style="display:none">
        <div class="compare-after-clip" id="compare-after-clip"><img id="compare-after-img" data-compare-day="${ui.compareB}" data-angle="${ui.compareAngle}" alt="After photo, Day ${ui.compareB}" style="display:none"></div>
        <div class="compare-divider" id="compare-divider" aria-hidden="true"><span>↔</span></div>
        <div class="overlay-corner before">Day ${ui.compareA} · Before</div><div class="overlay-corner after">Day ${ui.compareB} · After</div>
      </div>
      <label class="reveal-control"><span>Reveal after photo</span><input aria-label="Move before after reveal" type="range" min="0" max="100" id="compare-reveal" value="${ui.compareReveal}"><strong id="reveal-value">${ui.compareReveal}%</strong></label>
      <details class="align-fine-tune" id="align-fine-tune"><summary>Fine-tune alignment <span>Drag photo above or adjust precisely</span></summary><div class="align-sliders">
        <label>Scale <output id="zoom-value">100%</output><input id="align-zoom" type="range" min="50" max="210" step="1" value="${Math.round(alignTransform.scale*100)}"></label>
        <label>Horizontal <output id="panx-value">0%</output><input id="align-panx" type="range" min="-60" max="60" step="0.5" value="${alignTransform.dx}"></label>
        <label>Vertical <output id="pany-value">0%</output><input id="align-pany" type="range" min="-60" max="60" step="0.5" value="${alignTransform.dy}"></label>
        <label>Tilt <output id="rotate-value">0°</output><input id="align-rotate" type="range" min="-20" max="20" step="0.5" value="${alignTransform.angle}"></label>
      </div></details>
    </div>
    <p class="muted-xs" style="margin:13px 0 0">Auto align downloads a free pose model once (internet needed); detection runs privately in your browser. It corrects 2D framing—not perspective, posture, or body shape. Originals stay unchanged. Manual tweaks are saved on this device.</p>
  </section>`;
}
function parseHealthAttribute(tag,name){let re=new RegExp('\\b'+name+'="([^"]*)"');return tag.match(re)?.[1]||''}
async function importHealth(file){
  if(!/\.xml$/i.test(file.name))return toast('Unzip the Apple Health export first, then choose export.xml.');
  if(!confirm('Import Apple Health metrics for the 100-day course? The original XML stays on this device. This may take time for a very large export.'))return;
  toast('Reading Health export…');
  try{
    const data=new Map(), chunkSize=1024*1024;
    let buffer='',records=0;
    const accumulate=tag=>{
      const type=parseHealthAttribute(tag,'type');
      if(!/StepCount|BodyMass$|ActiveEnergyBurned|HeartRate$|SleepAnalysis/.test(type))return;
      const start=parseHealthAttribute(tag,'startDate');if(!start)return;
      const date=start.slice(0,10);if(date<START||date>dateFor(100))return;
      const day=data.get(date)||{points:new Map(),weight:null,weightTime:'',steps:0,activeCalories:0,hrTotal:0,hrCount:0,sleepHours:0};
      const raw=Number(parseHealthAttribute(tag,'value')),unit=parseHealthAttribute(tag,'unit');
      const end=parseHealthAttribute(tag,'endDate')||start;
      const category=type.includes('SleepAnalysis');
      if(category){
        const value=parseHealthAttribute(tag,'value');
        if(!/Asleep(Core|Deep|REM|Unspecified)|Asleep$/.test(value))return;
        const startD=new Date(start.replace(/([+-]\d\d)(\d\d)$/,'$1:$2'));const endD=new Date(end.replace(/([+-]\d\d)(\d\d)$/,'$1:$2'));
        if(!Number.isFinite(+startD)||!Number.isFinite(+endD))return;
        const hours=Math.max(0,Math.min(20,(endD-startD)/3600000));
        const k='sleep|'+start+'|'+end;if(!day.points.has(k)){day.points.set(k,hours);day.sleepHours+=hours}
      }else{
        if(!Number.isFinite(raw)||raw<0)return;
        let v=raw;
        if(type.endsWith('BodyMass')){
          if(/lb/i.test(unit))v=raw*.45359237;
          if(start>=day.weightTime){day.weight=v;day.weightTime=start}
        }else{
          if(type.includes('ActiveEnergyBurned')&&/kJ/i.test(unit))v=raw/4.184;
          const k=type+'|'+start+'|'+end;
          if(day.points.has(k)){let old=day.points.get(k);if(v<=old)return;if(type.includes('StepCount'))day.steps-=old;else if(type.includes('ActiveEnergyBurned'))day.activeCalories-=old;else if(type.endsWith('HeartRate'))day.hrTotal-=old}
          else if(type.endsWith('HeartRate'))day.hrCount++;
          day.points.set(k,v);
          if(type.includes('StepCount'))day.steps+=v;
          else if(type.includes('ActiveEnergyBurned'))day.activeCalories+=v;
          else if(type.endsWith('HeartRate'))day.hrTotal+=v;
        }
      }
      data.set(date,day);records++;
    };
    for(let offset=0;offset<file.size;offset+=chunkSize){
      buffer+=await file.slice(offset,offset+chunkSize).text();
      const re=/<Record\b[^>]*>/g;let match,end=0;
      while((match=re.exec(buffer))!==null){accumulate(match[0]);end=re.lastIndex}
      if(end)buffer=buffer.slice(end);
      if(buffer.length>4096){const last=buffer.lastIndexOf('<Record');buffer=last>=0?buffer.slice(last):buffer.slice(-64)}
      if(offset%(chunkSize*25)===0)await new Promise(r=>setTimeout(r,0));
    }
    if(!data.size)throw Error('No supported Health records were found between 26 Oct 2026 and 2 Feb 2027.');
    let imported=0;
    for(const [date,v]of data){
      const row={...store.health.daily[date],_updatedAt:Date.now()};
      if(v.weight!=null)row.weight=Number(v.weight.toFixed(2));
      if(v.steps)row.steps=Math.round(v.steps);
      if(v.activeCalories)row.activeCalories=Number(v.activeCalories.toFixed(1));
      if(v.hrCount)row.heartRate=Number((v.hrTotal/v.hrCount).toFixed(1));
      if(v.sleepHours)row.sleepHours=Number(v.sleepHours.toFixed(2));
      store.health.daily[date]=row;
      const day=dayForDate(date);
      if(v.weight!=null&&day>=1&&day<=100&&!dayData(day).metrics?.weight){touchDay(day,o=>{o.metrics??={};o.metrics.weight=String(v.weight.toFixed(1));o.metrics.weightSource='Apple Health import'})}
      imported++;
    }
    save();queueCloudSync();render({keepScroll:true});toast(`Imported ${imported} days of Health summaries`);
  }catch(e){toast('Health import failed: '+e.message)}
}
async function syncLocalPhotos(){
  if(!sync.connected)return;
  let uploaded=0;
  for(const [day,d] of Object.entries(store.days)){
    for(const angle of ['front','side','back']){
      if(!d.photos?.[angle]&&!((angle==='front')&&d.hasLocalPhoto))continue;
      if(d.cloudPhotos?.[angle])continue;
      let encoded=await photoGet(Number(day),angle);
      if(!encoded)continue;
      try{
        await apiRequest(`?op=photo&day=${day}&angle=${angle}`,{method:'PUT',headers:{'Content-Type':'image/jpeg'},body:dataURLtoBlob(encoded)});
        touchDay(Number(day),obj=>{obj.cloudPhotos??={};obj.cloudPhotos[angle]=true});uploaded++;
      }catch(err){console.warn('Photo pending cloud backup:',err.message)}
    }
  }
  if(uploaded){queueCloudSync();toast(`${uploaded} photos backed up to Netlify`)}
}
async function boot(){
  try{let r=await fetch('/course-register.json');if(r.ok)register=await r.json()}catch{}
  try{let r=await fetch('/site-settings.json');if(r.ok)siteSettings=await r.json()}catch{}
  render();
  if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
  if(sync.key&&navigator.onLine){try{await pullCloud(true);sync.connected=true;sync.status='Netlify connected';render({keepScroll:true});await pushCloud();await syncLocalPhotos()}catch{sync.key='';sync.status='Device only';render({keepScroll:true})}}
}
boot();
